import { supabase } from '../../lib/supabase';

export const GET = async () => {
  try {
    const { data, error } = await supabase
      .from('config')
      .select('voting_closed')
      .eq('id', 1)
      .single();

    if (error) {
      console.error("Erreur lecture config:", error);
      return new Response(JSON.stringify({ error: "Erreur lors de la lecture de la configuration" }), { status: 500 });
    }

    return new Response(JSON.stringify(data), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  } catch (err) {
    console.error("Exception config:", err);
    return new Response(JSON.stringify({ error: "Erreur serveur" }), { status: 500 });
  }
};

import { supabase } from '../../lib/supabase';

export const POST = async ({ request }) => {
  try {
    const body = await request.json();
    const { voter_slug, voter_name, king, queen, categories } = body;

    if (!voter_slug || !voter_name) {
      return new Response(JSON.stringify({ error: "Votant invalide" }), { status: 400 });
    }

    // Vérifier si les votes sont ouverts
    const { data: config } = await supabase.from('config').select('voting_closed').eq('id', 1).single();
    if (config?.voting_closed) {
      return new Response(JSON.stringify({ error: "Les votes sont clos" }), { status: 403 });
    }

    // Enregistrer le vote (upsert basé sur voter_slug)
    const { error } = await supabase.from('ballots').upsert({
      voter_slug,
      voter_name,
      king: king || null,
      queen: queen || null,
      votes: categories || {},
      created_at: new Date().toISOString()
    }, {
      onConflict: 'voter_slug'
    });

    if (error) {
      console.error("Erreur vote:", error);
      return new Response(JSON.stringify({ error: "Erreur lors de l'enregistrement du vote" }), { status: 500 });
    }

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  } catch (err) {
    console.error("Exception vote:", err);
    return new Response(JSON.stringify({ error: "Erreur serveur" }), { status: 500 });
  }
};

import { supabase } from '../../lib/supabase';

export const GET = async () => {
  try {
    const { data: ballots, error } = await supabase.from('ballots').select('*');
    if (error) throw error;

    const { data: categoriesData, error: catError } = await supabase.from('categories').select('*').order('position');
    if (catError) throw catError;

    // Dépouillement
    const results = {
      king: {},
      queen: {},
      categories: {}
    };

    categoriesData.forEach(c => {
      results.categories[c.id] = { name: c.name, votes: {} };
    });

    let totalVotes = ballots.length;

    ballots.forEach(ballot => {
      if (ballot.king) results.king[ballot.king] = (results.king[ballot.king] || 0) + 1;
      if (ballot.queen) results.queen[ballot.queen] = (results.queen[ballot.queen] || 0) + 1;

      if (ballot.votes) {
        Object.keys(ballot.votes).forEach(catId => {
          const candidate = ballot.votes[catId];
          if (results.categories[catId] && candidate) {
            results.categories[catId].votes[candidate] = (results.categories[catId].votes[candidate] || 0) + 1;
          }
        });
      }
    });

    // Formatage pour un affichage facile
    const formatPodium = (tally) => {
      return Object.entries(tally)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([name, count]) => ({ name, count }));
    };

    const formatCategory = (cat) => {
       const sorted = Object.entries(cat.votes).sort((a, b) => b[1] - a[1]);
       return {
         name: cat.name,
         total: sorted.reduce((sum, [, count]) => sum + count, 0),
         candidates: sorted.map(([name, count]) => ({ name, count }))
       };
    };

    return new Response(JSON.stringify({
      total: totalVotes,
      king: formatPodium(results.king),
      queen: formatPodium(results.queen),
      categories: Object.values(results.categories).map(formatCategory)
    }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });

  } catch (err) {
    console.error("Exception results:", err);
    return new Response(JSON.stringify({ error: "Erreur serveur lors du dépouillement" }), { status: 500 });
  }
};

export const POST = async ({ request }) => {
  try {
    const { code } = await request.json();
    const adminKey = import.meta.env.ADMIN_SECRET_KEY || process.env.ADMIN_SECRET_KEY;

    if (code === adminKey) {
      return new Response(JSON.stringify({ success: true, token: "admin_token_ok" }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    }

    return new Response(JSON.stringify({ error: "Code incorrect" }), { status: 401 });
  } catch (err) {
    console.error("Exception unlock:", err);
    return new Response(JSON.stringify({ error: "Erreur serveur" }), { status: 500 });
  }
};

import { supabase } from '../../../lib/supabase';

export const POST = async ({ request }) => {
  try {
    const { token } = await request.json();

    // Very basic token validation (in a real app, use JWT)
    if (token !== "admin_token_ok") {
      return new Response(JSON.stringify({ error: "Non autorisé" }), { status: 401 });
